def setup():
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':8,'axes.linewidth':.7,'ps.fonttype':42,'pdf.fonttype':42,
                         'savefig.facecolor':'white','axes.spines.top':False,'axes.spines.right':False})
    return plt

def save(fig,out,name):
    out.mkdir(parents=True,exist_ok=True)
    for ext in ['eps','pdf','png']:
        fig.savefig(out/(name+'.'+ext),format=ext,dpi=600 if ext=='eps' else 300)

def visible(family):
    return [r for r in family['rows'] if (r['status']=='complete' or r.get('construction_only_authorized',False)) and not(r['representation']=='minimizers' and r['tool'] in OMIT_MIN)]

def axis(ax,rows,column,divisor,title,ylabel):
    from matplotlib.ticker import LogLocator,NullFormatter,FuncFormatter
    ns=sorted({r['genomes'] for r in rows});ax.set_xscale('log',base=2);ax.set_yscale('log')
    ax.set_xticks(ns);ax.set_xticklabels([str(n) if n<1024 else str(n//1024)+'k' for n in ns],fontsize=7)
    ax.set_xlim(min(ns)/1.13,max(ns)*1.13);ys=[r[column]/divisor for r in rows if r.get(column) is not None and r[column]>0]
    low,high=min(ys),max(ys);pad=max(math.log10(high/low)*.075,.10);ax.set_ylim(low/10**pad,high*10**pad)
    ax.yaxis.set_major_locator(LogLocator(base=10,numticks=5));ax.yaxis.set_minor_locator(LogLocator(base=10,subs=(2,3,4,5,6,7,8,9),numticks=100));ax.yaxis.set_minor_formatter(NullFormatter())
    ax.yaxis.set_major_formatter(FuncFormatter(lambda v,p:format(v,'.2g')));ax.tick_params(axis='y',labelsize=7)
    for tool in [t for t in COLORS if t!='zindex']+['zindex']:
        for rep in ['kmers','minimizers']:
            rr=sorted([r for r in rows if r['tool']==tool and r['representation']==rep and r.get(column) is not None and r[column]>0],key=lambda r:r['genomes'])
            if not rr:continue
            x=[];y=[];previous=None
            for r in rr:
                if previous and r['genomes']!=previous*2:x.append(float('nan'));y.append(float('nan'))
                x.append(r['genomes']);y.append(r[column]/divisor);previous=r['genomes']
            ax.plot(x,y,color=COLORS[tool],linestyle='-' if rep=='kmers' else(0,(5,2.8)),lw=2.1 if tool=='zindex' else 1.5,
                    marker=MARKERS[tool],markersize=3.8 if tool=='zindex' else 3.2,markerfacecolor=COLORS[tool],markeredgecolor=COLORS[tool],markeredgewidth=.4,zorder=8 if tool=='zindex' else 3)
    ax.set_xlabel('Number of genomes (log2)',fontsize=8,labelpad=4);ax.set_ylabel(ylabel,fontsize=8,labelpad=4)
    ax.grid(which='major',color='#dddddd',linewidth=.55);ax.set_axisbelow(True)

